INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT159-S1-Q9$batch04$, 159, 1, 9, $batch04$Paradox$batch04$, $batch04$Market studies confirm that consumers shopping for automobiles primarily seek those that are most reliable. An automobile is reliable if it very rarely breaks down and it does not require significantly more maintenance than average. Strangely enough, however, some of the most reliable models do not sell well with those who say they care most about reliability.$batch04$, $batch04$Which one of the following, if true, most helps to resolve the apparent discrepancy in the information above?$batch04$, $batch04$B$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q9$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$Consumers who are shopping for an automobile claim to care more about reliability than about fuel efficiency.$batch04$, $batch04$Deepens Paradox$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$Consumers often choose automobile models based on a reputation for reliability, and reputations can be out of date.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$Some owners of reliable automobiles are reluctant to trade them in for newer vehicles and tend to hold on to them for the life of the automobile.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$Some automobile models that have been shown to require a lot of maintenance very rarely break down.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$Some of the most stylish automobiles are some of the most unreliable.$batch04$, $batch04$Out of Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$Car shoppers mainly look for the most reliable models.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$Some of the most reliable models sell poorly to the people who say they care most about reliability?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Those shoppers want reliability, but they have to judge it somehow. If they judge it in a way that can be wrong, they may miss the cars that are actually reliable.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a reason shoppers who want reliability fail to identify the reliable models.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT159-S1-Q9$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$If shoppers care more about reliability than fuel efficiency, it is even stranger that they skip the reliable cars.$batch04$), ($batch04$B$batch04$, $batch04$Shoppers go by a model's reputation, and reputations can be out of date. A model that has become reliable may still carry an old reputation for breaking down, so reliability-minded shoppers pass it by.$batch04$), ($batch04$C$batch04$, $batch04$Owners keeping their reliable cars does not explain why new shoppers do not buy those models.$batch04$), ($batch04$D$batch04$, $batch04$A car that needs a lot of maintenance is not reliable by the stimulus's definition, so these models are not the ones in question.$batch04$), ($batch04$E$batch04$, $batch04$Unreliable stylish cars do not explain why reliable cars sell poorly.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT159-S1-Q9$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
